      'itemtype'            => $itemtype,
      'entity_restrict'     => $_POST['entity_restrict'],
      'table'               => $table,
      'multiple'            => $_POST["multiple"],
      'myname'              => $_POST["myname"],
      'rand'                => $_POST["rand"],
      '_idor_token'         => Session::getNewIDORToken($itemtype),
