				"<\\s*img([^>]*)src\\s*=\\s*[\"\']?([^\'\">]*)[\"\']?([^>]*)>",
				"<img$1src=\"http://" + serverName
				+ "$2\"$3>");
		// Replacing links "A HREF" like tags
		message = message
		.replaceAll(
				"<\\s*link([^>]*)href\\s*=\\s*[\"\']?([^\'\">]*)[\"\']?([^>]*)>",
				"<link$1href=\"http://"
				+ serverName
				+ "$2\"$3>");
		// Replacing links "SCRIPT" like tags
